# Generated by build.py from recipe.yml for recipe ftp-create-folders-while-uploading. Do not edit.
Set-Location $PSScriptRoot
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--allow-anonymous', '--allow-uploads', '--list-directories', 'ftp://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s --ftp-create-dirs -T report.txt ftp://127.0.0.1:8080/2026/11/12/report.txt } finally { Stop-Process $server0 }
